{"code":"const listed = await tools.list_agents({ scope: "children" });
const reporting = listed.find(agent => agent.label === "Reporting child");
const failing = listed.find(agent => agent.label === "Failing child");
if (!reporting || !failing) throw new Error("expected both children");
await tools.get_agent_status({ agent_id: reporting.id });
await tools.get_agent_status({ agent_id: failing.id });
const steer = await tools.steer_agent({ agent_id: reporting.id, message: "Release after report." }).catch(error => String(error));
const interrupted = await tools.interrupt_agent({ agent_id: failing.id }).catch(error => String(error));
const closed = await tools.close_agent({ agent_id: failing.id }).catch(error => String(error));
return { steer, interrupted, closed };","description":"Inspect and control both children"}

